import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.D1JEzK2q.js";const u=JSON.parse('{"title":"Claude Gateway — CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),r={name:"reference/cli.md"};function s(n,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-gateway-—-cli-reference" tabindex="-1">Claude Gateway — CLI Reference <a class="header-anchor" href="#claude-gateway-—-cli-reference" aria-label="Permalink to &quot;Claude Gateway — CLI Reference&quot;">​</a></h1><blockquote><p><strong>Auto-generated from the route manifest</strong> (<code>scripts/gen-cli.ts</code>). Do not edit by hand. See the <a href="https://0xmaxma.github.io/claude-gateway/api/" target="_blank" rel="noreferrer">HTTP API reference</a> for integration protocols.</p></blockquote><p>The <code>claude-gateway</code> binary accepts friendly <code>&lt;noun&gt; &lt;verb&gt;</code> subcommands.</p><p><strong>Starting the gateway is explicit.</strong> <code>claude-gateway gateway start</code> runs the server in the foreground; every other invocation — no arguments, <code>--help</code>, or a typo — prints help or an error and exits, so exploring the CLI can never leave a stray server on the gateway port.</p><blockquote><p><strong>Upgrading from &lt; 1.8:</strong> a service unit whose <code>ExecStart</code> runs the binary with no command still starts the server, with a deprecation warning. Change it to <code>claude-gateway gateway start</code> (or reinstall the unit with <code>claude-gateway service install</code>); a future release will drop the shim.</p></blockquote><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--url &lt;url&gt;</code></td><td>Gateway base URL (else <code>$CLAUDE_GATEWAY_URL</code>, else <code>http://&lt;bind&gt;:&lt;port&gt;</code> when a gateway is running on this host, else <code>config.gateway.publicUrl</code>)</td></tr><tr><td><code>--key &lt;key&gt;</code></td><td>API key (else <code>$CLAUDE_GATEWAY_API_KEY</code>, else the first admin key in config)</td></tr><tr><td><code>--json</code></td><td>Print the raw JSON response only (stdout reserved for JSON)</td></tr><tr><td><code>--data &lt;json&gt;</code></td><td>JSON object merged into the request body (write commands)</td></tr><tr><td><code>--help</code></td><td>Show help for the command</td></tr></tbody></table><p><strong>Which address the CLI uses.</strong> <code>config.gateway.publicUrl</code> describes <em>this</em> gateway as seen from outside, so on the gateway&#39;s own host both addresses are the same server — the public one just adds a reverse-proxy hop. Routing through it makes every command depend on that proxy, and a proxy that enforces its own authentication (which the CLI has no credentials for) answers <code>401</code> to commands that work over loopback. So when a gateway is running on this host (detected from the pidfile it writes on boot, a file read and a signal-0 — no subprocess), the local bind wins over <code>publicUrl</code>. <code>--url</code> and <code>$CLAUDE_GATEWAY_URL</code> still override, for deliberately exercising the proxy path or reaching another host.</p><p>The port comes from that same pidfile, whose second line is the port the gateway actually bound. <code>$PORT</code> describes the shell running the CLI, not the shell the server was started from: after <code>PORT=9000 make start</code> in one terminal, a plain CLI in another would otherwise address port 10850, where nothing listens. <code>$PORT</code> is still the fallback when no gateway is running, or when the pidfile predates the port line.</p><p>A pidfile can also outlive its gateway — killed without cleanup, and the pid reissued to some unrelated process. The local address is still preferred, but <code>publicUrl</code> names the same gateway, so a local address that cannot be reached <strong>at all</strong> is retried once there, with a line on stderr saying so. An address that answered — including with an error — is never retried: the gateway was reached, and asking somewhere else would only hide its answer.</p><p><code>agents</code> and <code>channels</code> settle the address once, at the start of the session, rather than per request: they thread one base URL through an interactive flow, so a mid-wizard switch would be worse than a single decision up front. The rule for choosing is the same one described above.</p><p><code>gateway status</code> and <code>service install</code> go further: they report on the gateway <em>process</em> on this host, so they resolve <code>--url</code> → <code>http://&lt;bind&gt;:&lt;port&gt;</code> and ignore <code>$CLAUDE_GATEWAY_URL</code> and <code>publicUrl</code> entirely — a proxy still answering from a different instance would otherwise report a dead local service as healthy.</p><p><code>doctor</code> probes the address the CLI will use (that check decides its exit code) and adds an <strong>informational</strong> probe of the other address whenever the two differ, marked <code>[--]</code>. A public URL that rejects an unauthenticated <code>/health</code> is reported, but never fails <code>doctor</code> — the CLI is not using that address. It also checks <code>gateway.publicUrl</code> itself (marked <code>[warn]</code> when unset — a capability gap, not a misconfiguration — and <code>[!!]</code> when set but nothing answers), since that value backs <code>generate_image</code> reference edits, <code>share_file</code>, and <code>/cli</code>, and nothing else surfaces its absence (#472). Skipped when <code>--url</code>/<code>$CLAUDE_GATEWAY_URL</code> point at a different host — it is this host&#39;s own config file, so it is not context for a question about another machine.</p><p><strong>Colour.</strong> Help and diagnostic text is coloured only when the stream it is going to is a terminal — stdout for a requested help listing, stderr for everything else — so piping either one strips the escapes. Set <code>NO_COLOR</code> to turn colour off, or <code>FORCE_COLOR=1</code> to keep it through a pipe; <code>NO_COLOR</code> wins if both are set. Result output is never coloured at all: <code>printResult</code> does not touch the palette, so <code>--json</code> piped into <code>jq</code> is unaffected by any of this.</p><h2 id="lifecycle-diagnostics-do-not-require-a-running-server" tabindex="-1">Lifecycle &amp; diagnostics (do not require a running server) <a class="header-anchor" href="#lifecycle-diagnostics-do-not-require-a-running-server" aria-label="Permalink to &quot;Lifecycle &amp; diagnostics (do not require a running server)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway gateway start</code></td><td>Run the gateway in the foreground (the only command that boots it)</td></tr><tr><td><code>claude-gateway gateway status</code></td><td>Show the owning manager and <code>/health</code> on the local bind address</td></tr><tr><td><code>claude-gateway gateway restart</code></td><td>Restart via the owning manager (systemd-user/systemd-system/pm2/foreground)</td></tr><tr><td><code>claude-gateway gateway stop</code></td><td>Stop the gateway</td></tr><tr><td><code>claude-gateway gateway logs [--follow] [--lines &lt;n&gt;] [--agent &lt;id&gt;] [--json]</code></td><td>Read the gateway log files directly (no running server needed)</td></tr><tr><td><code>claude-gateway doctor</code></td><td>Check config, key resolution, owning manager, and connectivity</td></tr><tr><td><code>claude-gateway debug-bundle</code></td><td>Write a small redacted diagnostics bundle for a stuck session</td></tr><tr><td><code>claude-gateway api &lt;METHOD&gt; &lt;path&gt;</code></td><td>Escape hatch: call any endpoint directly</td></tr></tbody></table><p>A bare <code>claude-gateway gateway</code> (or <code>crons</code>, <code>service</code>, …) prints its verbs and exits <strong>1</strong> — you forgot the verb. The same listing with <code>--help</code> exits <strong>0</strong>, and <code>-h</code> is accepted wherever <code>--help</code> is. <code>--help</code> never has a side effect: <code>debug-bundle --help</code> prints usage rather than writing a bundle.</p><p><strong>Where help goes.</strong> A listing you asked for (<code>--help</code>, or a bare <code>claude-gateway</code>) is the command&#39;s result and goes to <strong>stdout</strong>, so <code>claude-gateway --help | less</code> and <code>claude-gateway crons --help | grep create</code> work. The same listing printed <em>because</em> the invocation was wrong goes to <strong>stderr</strong> with a non-zero exit, leaving stdout carrying results only. Single-dash tokens other than <code>-h</code>/<code>-V</code> are values, not flags, so a <code>-5</code> argument is never mistaken for one.</p><h2 id="running-as-a-service" tabindex="-1">Running as a service <a class="header-anchor" href="#running-as-a-service" aria-label="Permalink to &quot;Running as a service&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway service install [--manager systemd|pm2] [--scope user|system] [--run-as &lt;user&gt;] [--after &lt;target,...&gt;] [--env-file &lt;path&gt;] [--env KEY=VALUE,...] [--config &lt;path&gt;] [--yes] [--print] [--force]</code></td><td>Generate and start a service</td></tr><tr><td><code>claude-gateway service status [--manager systemd|pm2] [--scope user|system]</code></td><td>Report installed/enabled/active state as JSON</td></tr><tr><td><code>claude-gateway service uninstall [--manager systemd|pm2] [--scope user|system] [--yes]</code></td><td>Stop and remove the service</td></tr><tr><td><code>claude-gateway service start [--manager systemd|pm2] [--scope user|system]</code></td><td>Start the installed service (found even when inactive)</td></tr><tr><td><code>claude-gateway service stop [--manager systemd|pm2] [--scope user|system]</code></td><td>Stop the installed service</td></tr><tr><td><code>claude-gateway service restart [--manager systemd|pm2] [--scope user|system]</code></td><td>Restart the installed service (starts it if it was stopped)</td></tr></tbody></table><ul><li><code>systemd</code> (the default) installs a <strong>user</strong> unit at <code>~/.config/systemd/user/claude-gateway.service</code> — no <code>sudo</code>, and it runs as the user that owns <code>~/.claude-gateway</code>. Run <code>loginctl enable-linger &lt;user&gt;</code> once if it must survive logout.</li><li><code>--scope system</code> (systemd only) installs a root-owned unit at <code>/etc/systemd/system/claude-gateway.service</code> instead, for automated/infra provisioning that needs a fixed system account. Requires already running as root (never escalates via <code>sudo</code>) and <code>--run-as &lt;user&gt;</code>, which becomes the unit&#39;s <code>User=</code>; <code>WantedBy=</code> is <code>multi-user.target</code> instead of <code>default.target</code>, and the <code>loginctl</code> hint is skipped. It never triggers the system-scope conflict check below against itself.</li><li><code>--after &lt;target,...&gt;</code>, <code>--env-file &lt;path&gt;</code>, and <code>--env KEY=VALUE,...</code> customize the generated unit (either scope): extra <code>After=</code> ordering targets, an <code>EnvironmentFile=-&lt;path&gt;</code> for secrets that never appear in the unit text, and additional non-secret <code>Environment=</code> lines. <code>--env</code> refuses to override <code>HOME</code>, <code>PATH</code>, or <code>GATEWAY_CONFIG</code>.</li><li>Every path in the generated unit (node, entry point, config, working directory) is absolute, and <code>ExecStart</code> always uses the explicit <code>gateway start</code> command. No secrets are written into the unit — the gateway reads <code>~/.claude-gateway/.env</code> itself.</li><li><code>--print</code> shows exactly what would be installed and exits without touching anything. Install and uninstall both ask for confirmation unless <code>--yes</code> is given (uninstall stops a running gateway), and refuse to run non-interactively without it.</li><li><code>install</code> verifies <code>/health</code> on the <strong>local bind address</strong>, and <code>uninstall</code> reports the state the manager actually reports afterwards — never the state that was intended.</li><li>Exit codes for <code>install</code>, <code>start</code> and <code>restart</code> (every command that is supposed to leave a running gateway behind): <code>0</code> fully healthy, <code>1</code> the action itself failed — install/enable, or the start/restart — or a validation/confirmation gate refused, <code>2</code> the action succeeded but <code>/health</code> never answered within the poll window. Distinguishing <code>1</code> from <code>2</code> by exit code alone means a caller doesn&#39;t have to parse the JSON result on stdout just to tell &quot;didn&#39;t happen&quot; apart from &quot;happened, health unconfirmed&quot;. <code>status</code>, <code>stop</code> and <code>uninstall</code> never return <code>2</code>; they are not trying to produce a service that answers.</li><li>(systemd, user-scope installs) <code>install</code> refuses by default if a <code>claude-gateway.service</code> unit already exists and is enabled or active at <em>system</em> scope (e.g. from provisioning outside this CLI) — it prints the exact <code>sudo systemctl disable --now claude-gateway.service</code> to resolve it; pass <code>--force</code> to install anyway.</li><li>Re-running <code>install</code> against an already-active unit whose rendered content changed restarts it automatically; unchanged content leaves the running unit alone.</li><li>After installing, <code>gateway restart</code>/<code>stop</code> detect and drive that same service.</li><li><code>service start\\|stop\\|restart</code> act on the unit selected by <code>--manager</code>/<code>--scope</code>, the same way <code>status</code>/<code>uninstall</code> do — discovered from disk, so they find an installed-but-inactive service too. This is different from <code>gateway restart</code>/<code>stop</code>, which only drive whatever manager is currently reported <em>active</em>, and can never start a stopped service. <code>stop</code> on an already-stopped (or never installed) service is a no-op success, matching <code>uninstall</code>&#39;s idempotence; <code>start</code>/<code>restart</code> on a service that was never installed is an error telling you to run <code>service install</code> first.</li><li><code>start</code> on a service that is <em>already</em> running still checks <code>/health</code> and still reports it, so the result is the same shape either way and <code>2</code> still means &quot;running, but answering nothing&quot; — a process manager calling a wedged gateway <code>active</code> is precisely the case a health check is for.</li></ul><h2 id="app-store-docker-compose-apps" tabindex="-1">App Store (Docker-compose apps) <a class="header-anchor" href="#app-store-docker-compose-apps" aria-label="Permalink to &quot;App Store (Docker-compose apps)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway app list</code></td><td>List installed apps and their status</td></tr><tr><td><code>claude-gateway app start &lt;name&gt;</code></td><td>Start a stopped app</td></tr><tr><td><code>claude-gateway app stop &lt;name&gt;</code></td><td>Stop a running app</td></tr><tr><td><code>claude-gateway app restart &lt;name&gt;</code></td><td>Restart an app</td></tr><tr><td><code>claude-gateway app uninstall &lt;name&gt; [--yes]</code></td><td>Remove an app&#39;s containers and installed files (keeps backups)</td></tr><tr><td><code>claude-gateway app install &lt;source&gt; [--version &lt;v&gt;] [--commit &lt;sha&gt;] [--env KEY=VALUE,...] [--env-file &lt;path&gt;] [--ports NAME=PORT,...] [--wait]</code></td><td>Install an app</td></tr></tbody></table><p>A thin client over <code>/v1/apps</code> (see the <a href="https://0xmaxma.github.io/claude-gateway/api/apps.html" target="_blank" rel="noreferrer">Apps API</a> for the full HTTP reference) — every action is the same admin-gated call the dashboard&#39;s App Store UI makes, so there is only one authorization/behavior path to keep correct.</p><p><code>&lt;source&gt;</code> is classified by shape, so there is no separate <code>--registry-app</code>/<code>--github-url</code>/ <code>--local-path</code> flag for the common case: an <code>http(s)://</code> URL is a GitHub source, a path starting with <code>/</code>, <code>./</code>, <code>../</code>, or <code>~</code> is a local (symlinked, dev-mode) source, and anything else is a registry app name. <code>--version</code> only applies to a registry source; <code>--commit</code> only to a GitHub source (both optional — a GitHub install with no <code>--commit</code> resolves <code>HEAD</code>).</p><p><code>--env</code> and <code>--env-file</code> both fill the install&#39;s <code>env_vars</code>, and are merged (<code>--env</code> wins on a conflict). Prefer <code>--env-file</code> for secrets: a value passed on the command line is readable by every local user in <code>/proc/&lt;pid&gt;/cmdline</code> for as long as the install runs, and is written verbatim to the caller&#39;s shell history. The file is ordinary dotenv text — <code>KEY=VALUE</code> lines, <code>#</code> comments, and surrounding quotes stripped — parsed exactly like the gateway&#39;s own <code>.env</code>.</p><p><code>install</code> is asynchronous: the server returns a <code>jobId</code> immediately and this command never reports &quot;installed&quot; on its own — only that the job was <strong>accepted</strong>. Poll it with <code>claude-gateway api GET /v1/apps/jobs/&lt;jobId&gt;</code>, or pass <code>--wait</code> to have this command poll here and print the real outcome (streaming the job&#39;s log lines to stderr as they arrive).</p><p><code>uninstall</code> asks for confirmation unless <code>--yes</code> is given, and refuses to run non-interactively without it — same convention as <code>service install</code>/<code>uninstall</code>. It removes the app&#39;s containers and installed files, but never its backups.</p><h2 id="versions-updates" tabindex="-1">Versions &amp; updates <a class="header-anchor" href="#versions-updates" aria-label="Permalink to &quot;Versions &amp; updates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway version</code></td><td>Print the installed gateway version</td></tr><tr><td><code>claude-gateway update check</code></td><td>Read-only: installed vs. published gateway version</td></tr><tr><td><code>claude-gateway update [--yes]</code></td><td>Show current → target, confirm, then <code>npm install -g</code> the latest</td></tr><tr><td><code>claude-gateway claude version</code></td><td>Print the installed Claude Code version</td></tr><tr><td><code>claude-gateway claude update check</code></td><td>Read-only version check for Claude Code</td></tr><tr><td><code>claude-gateway claude update [--yes]</code></td><td>Update Claude Code through its own native updater</td></tr></tbody></table><p>Both use the same detection and install strategy as the dashboard&#39;s Update button (<code>src/packages/registry.ts</code>). Claude Code is updated by its native updater, never by <code>npm install -g</code> — that would install a second copy that isn&#39;t the binary on <code>PATH</code>. Updating the gateway replaces the files on disk; the running process keeps serving the previous build until <code>claude-gateway gateway restart</code>.</p><h2 id="agents-channels-require-a-running-server" tabindex="-1">Agents &amp; channels (require a running server) <a class="header-anchor" href="#agents-channels-require-a-running-server" aria-label="Permalink to &quot;Agents &amp; channels (require a running server)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway agents list</code></td><td>List agents accessible by this key</td></tr><tr><td><code>claude-gateway agents create [id] [--description &lt;v&gt;]</code></td><td>Interactive wizard — generate workspace files, confirm, optionally connect Telegram/Discord</td></tr><tr><td><code>claude-gateway agents update [--agent &lt;id&gt;]</code></td><td>Regenerate AGENTS.md, or connect/update/disconnect Telegram/Discord/LINE/Slack</td></tr><tr><td><code>claude-gateway channels pending --agent &lt;id&gt; [--channel telegram|discord]</code></td><td>List incoming pairing requests</td></tr><tr><td><code>claude-gateway channels approve --agent &lt;id&gt; --channel &lt;v&gt; --code &lt;v&gt;</code></td><td>Approve a pending pairing request</td></tr><tr><td><code>claude-gateway channels deny --agent &lt;id&gt; --channel &lt;v&gt; --code &lt;v&gt;</code></td><td>Deny and remove a pending pairing request</td></tr></tbody></table><h2 id="resource-commands" tabindex="-1">Resource commands <a class="header-anchor" href="#resource-commands" aria-label="Permalink to &quot;Resource commands&quot;">​</a></h2><h3 id="crons" tabindex="-1"><code>crons</code> <a class="header-anchor" href="#crons" aria-label="Permalink to &quot;`crons`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>claude-gateway crons create --agentId &lt;v&gt; --name &lt;v&gt; [--type &lt;v&gt;] [--schedule &lt;v&gt;] [--scheduleKind &lt;v&gt;] [--scheduleAt &lt;v&gt;] [--command &lt;v&gt;] [--prompt &lt;v&gt;]</code></td><td>POST</td><td><code>/v1/crons</code></td><td>key</td><td>Create a cron job</td></tr><tr><td><code>claude-gateway crons delete &lt;id&gt;</code></td><td>DELETE</td><td><code>/v1/crons/:id</code></td><td>key</td><td>Delete a cron job</td></tr><tr><td><code>claude-gateway crons get &lt;id&gt;</code></td><td>GET</td><td><code>/v1/crons/:id</code></td><td>key</td><td>Get a single cron job</td></tr><tr><td><code>claude-gateway crons list [--agent &lt;v&gt;]</code></td><td>GET</td><td><code>/v1/crons</code></td><td>key</td><td>List cron jobs accessible by this key</td></tr><tr><td><code>claude-gateway crons run &lt;id&gt;</code></td><td>POST</td><td><code>/v1/crons/:id/run</code></td><td>key</td><td>Trigger a cron job now</td></tr><tr><td><code>claude-gateway crons runs &lt;id&gt; [--limit &lt;v&gt;]</code></td><td>GET</td><td><code>/v1/crons/:id/runs</code></td><td>key</td><td>Get cron job run history</td></tr><tr><td><code>claude-gateway crons status</code></td><td>GET</td><td><code>/v1/crons/status</code></td><td>key</td><td>Cron scheduler status</td></tr><tr><td><code>claude-gateway crons update &lt;id&gt; [--name &lt;v&gt;] [--type &lt;v&gt;] [--schedule &lt;v&gt;] [--scheduleKind &lt;v&gt;] [--scheduleAt &lt;v&gt;] [--timezone &lt;v&gt;] [--command &lt;v&gt;] [--prompt &lt;v&gt;] [--telegram &lt;v&gt;] [--discord &lt;v&gt;] [--timeoutMs &lt;v&gt;] [--deleteAfterRun] [--enabled]</code></td><td>PUT</td><td><code>/v1/crons/:id</code></td><td>key</td><td>Update a cron job</td></tr></tbody></table>',36)])])}const p=t(r,[["render",s]]);export{u as __pageData,p as default};
